// Real production domain, confirmed against the Google Business Profile
// listing (which lists it without "www" and over http; https + no-www is
// enforced here as the canonical form). Used for canonical URLs, Open
// Graph/Twitter tags, JSON-LD @id/url fields, and the sitemap generated by
// scripts/prerender.ts. Keep public/robots.txt's Sitemap: line in sync.
export const SITE_URL = 'https://visalatchimanufacturing.com';

export const SITE_NAME = 'Visalatchi Manufactures';

// Minimum order quantities, by box size. Large boxes (TV, fan, appliance,
// master and export cartons) run from 5,000 units; small boxes, mailers, food
// packs and bags from 10,000 units. Every product's moq in data/products.ts
// must be one of these two values, and copy should reference them, never a
// hard-coded third number.
export const MOQ_LARGE = 5000;
export const MOQ_SMALL = 10000;
export const MOQ_RULE =
  'Minimum order 5,000 units for large boxes (TV, fan, appliance, master and export cartons) and 10,000 units for small boxes, mailers, food packs and bags.';

// Self-hosted brand assets (public/logo.jpg, public/og-image.png). Previously
// hot-linked from a googleusercontent "aida-public" generated-asset URL, which
// can expire and silently break the logo in schema, OG cards and the navbar.
// Single source of truth for Seo.tsx, prerender.ts and schema.ts.
export const LOGO_PATH = '/logo.jpg';
/** Small WebP versions for on-page display (logo renders at 24-48 px). */
export const LOGO_SRCSET = '/logo-96.webp 96w, /logo-192.webp 192w';
export const LOGO_URL = `${SITE_URL}${LOGO_PATH}`;
export const OG_IMAGE_URL = `${SITE_URL}/og-image.png`;

// Official third-party profiles for the Organization schema's sameAs (entity
// signal for Google's Knowledge Graph and AI engines). Add each profile URL
// here as it goes live: IndiaMART, TradeIndia, LinkedIn, JustDial, Facebook.
// Only list profiles that exist and use the exact same name/address/phone.
export const SAME_AS: string[] = [
  'https://maps.app.goo.gl/F9VCUnqTkmb3cx568',
];

export const PLANT_ADDRESS = {
  streetAddress: 'No 10/4B Village Street, Sadayan Kuppam Pattai, Thiruvottiyur',
  addressLocality: 'Chennai',
  addressRegion: 'Tamil Nadu',
  postalCode: '600019',
  addressCountry: 'IN',
};

// One human-readable address string, built from PLANT_ADDRESS so the plant
// address used in the Footer's map link, the Footer's map embed, and the
// ContactView map embed can never drift apart into three slightly different
// strings (which is exactly the kind of NAP inconsistency that hurts local
// SEO trust).
export const PLANT_ADDRESS_FULL = `${PLANT_ADDRESS.streetAddress}, ${PLANT_ADDRESS.addressLocality} ${PLANT_ADDRESS.postalCode}, ${PLANT_ADDRESS.addressRegion}, India`;

// Exact coordinates of the verified Google Business Profile pin (resolved
// from https://maps.app.goo.gl/F9VCUnqTkmb3cx568), not a geocoded guess from
// the address text. Used for the map embeds and the LocalBusiness schema's
// geo field, both more accurate signals than an address string lookup.
export const PLANT_COORDS = { lat: 13.1663165, lng: 80.3008765 };

// The actual GBP share link. Used for "Get directions" links instead of a
// constructed maps search URL, since this is the literal link Google
// generated for the verified listing.
export const PLANT_MAPS_SHARE_URL = 'https://maps.app.goo.gl/F9VCUnqTkmb3cx568';

export const PLANT_MAPS_EMBED_SRC = `https://www.google.com/maps?q=${PLANT_COORDS.lat},${PLANT_COORDS.lng}&z=17&output=embed`;

// City-level courier dispatch coverage across Tamil Nadu. Framed as "we
// dispatch to" (true, pan-India courier network), not "we are near you" or
// "we operate a branch in" (which would be false for a single-plant
// business). City-level only, no neighborhoods or industrial estates as
// separate entries, per Google's June 2025 guidance against state/country
// level service areas and to avoid the doorway-page pattern.
//
// IMPORTANT: the current 4 (Chennai, Madurai, Coimbatore, Tiruchirappalli)
// are what GBP's own "Service area" field declares as of 2026-08-13. The
// remaining 8 below are added here because they're truthfully served by the
// existing pan-India courier network, but GBP itself has NOT been updated
// to match yet — update GBP's service area to include them too, so this
// list and the live GBP listing stay in sync (mismatched NAP/service-area
// data across platforms is a real local-SEO trust penalty).
